from typing import Any, Dict, Optional

class Warehouse:
    # Symbolic constants to replace magic strings
    STATUS_SHIPPED = "Shipped"
    STATUS_NOT_FOUND = False  # Using False as a sentinel to match original behavior

    def __init__(self):
        self._inventory: Dict[str, Dict[str, Any]] = {}  # Product ID: Product
        self._orders: Dict[str, Dict[str, Any]] = {}  # Order ID: Order

    @property
    def inventory(self) -> Dict[str, Dict[str, Any]]:
        return self._inventory

    @property
    def orders(self) -> Dict[str, Dict[str, Any]]:
        return self._orders

    def _get_product(self, product_id: str) -> Optional[Dict[str, Any]]:
        return self._inventory.get(product_id)

    def _is_product_in_inventory(self, product_id: str) -> bool:
        return product_id in self._inventory

    def _get_order(self, order_id: str) -> Optional[Dict[str, Any]]:
        return self._orders.get(order_id)

    def _is_order_in_orders(self, order_id: str) -> bool:
        return order_id in self._orders

    def add_product(self, product_id: str, name: str, quantity: int) -> None:
        if self._is_product_in_inventory(product_id):
            self._increase_product_quantity(product_id, quantity)
        else:
            self._create_product(product_id, name, quantity)

    def _create_product(self, product_id: str, name: str, quantity: int) -> None:
        self._inventory[product_id] = {'name': name, 'quantity': quantity}

    def _increase_product_quantity(self, product_id: str, quantity: int) -> None:
        self._inventory[product_id]['quantity'] += quantity

    def update_product_quantity(self, product_id: str, quantity: int) -> None:
        if self._is_product_in_inventory(product_id):
            self._increase_product_quantity(product_id, quantity)

    def get_product_quantity(self, product_id: str) -> Any:
        product = self._get_product(product_id)
        if product is not None:
            return product['quantity']
        return self.STATUS_NOT_FOUND

    def create_order(self, order_id: str, product_id: str, quantity: int) -> Any:
        if self._has_sufficient_stock(product_id, quantity):
            self._fulfill_order(order_id, product_id, quantity)
            return True
        return self.STATUS_NOT_FOUND

    def _has_sufficient_stock(self, product_id: str, quantity: int) -> bool:
        current_quantity = self.get_product_quantity(product_id)
        if current_quantity is self.STATUS_NOT_FOUND:
            return False
        return current_quantity >= quantity

    def _fulfill_order(self, order_id: str, product_id: str, quantity: int) -> None:
        self.update_product_quantity(product_id, -quantity)
        self._orders[order_id] = {
            'product_id': product_id,
            'quantity': quantity,
            'status': self.STATUS_SHIPPED
        }

    def change_order_status(self, order_id: str, status: str) -> Any:
        if self._is_order_in_orders(order_id):
            self._update_order_status(order_id, status)
            return True
        return self.STATUS_NOT_FOUND

    def _update_order_status(self, order_id: str, status: str) -> None:
        self._orders[order_id]['status'] = status

    def track_order(self, order_id: str) -> Any:
        order = self._get_order(order_id)
        if order is not None:
            return order['status']
        return self.STATUS_NOT_FOUND
